import{_ as t,a as d,o as r,a4 as a}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse(`{"title":"Revoke a GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"revoke-gdpr-request","title":"Revoke a GDPR Request","description":"Withdraw a pending or processing GDPR data request owned by the authenticated customer.","request":"POST /api/shop/gdpr-requests/12/revoke\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"{\\n  \\"id\\": 12,\\n  \\"type\\": \\"delete\\",\\n  \\"status\\": \\"revoked\\",\\n  \\"message\\": \\"Please delete my account data.\\",\\n  \\"email\\": \\"jane@example.com\\",\\n  \\"revokedAt\\": \\"2026-06-25T11:05:00.000000Z\\",\\n  \\"createdAt\\": \\"2026-06-25T10:30:00.000000Z\\",\\n  \\"updatedAt\\": \\"2026-06-25T11:05:00.000000Z\\",\\n  \\"successMessage\\": \\"Your GDPR data request has been revoked successfully.\\",\\n  \\"customer\\": {\\n    \\"_id\\": 7\\n  }\\n}\\n","commonErrors":[{"error":"400 Bad Request","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before revoking a request"},{"error":"422 Unprocessable Entity","cause":"The request is not in a pending or processing state","solution":"Only pending or processing requests can be revoked"},{"error":"404 Not Found","cause":"The request does not exist or is not owned by the authenticated customer","solution":"Only request IDs belonging to the logged-in customer can be revoked"},{"error":"401 Unauthorized","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/gdpr-requests/revoke-gdpr-request.md","filePath":"api/rest-api/shop/gdpr-requests/revoke-gdpr-request.md","lastUpdated":1783420618000}`),s={name:"api/rest-api/shop/gdpr-requests/revoke-gdpr-request.md"};function o(n,e,i,c,u,h){return r(),d("div",null,e[0]||(e[0]=[a('<h1 id="revoke-a-gdpr-request" tabindex="-1">Revoke a GDPR Request <a class="header-anchor" href="#revoke-a-gdpr-request" aria-label="Permalink to &quot;Revoke a GDPR Request&quot;">​</a></h1><p>Withdraw a GDPR data request the customer raised earlier. Revoking sets the request&#39;s status to <code>revoked</code> and stamps <code>revokedAt</code>. A request can only be revoked while it is still <code>pending</code> or <code>processing</code> — once it has been declined or approved it can no longer be revoked. The response carries a one-time <code>successMessage</code>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/gdpr-requests/{id}/revoke</span></span></code></pre></div><p>Send an empty request body.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the endpoint returns <strong>HTTP 400</strong> with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> The feature has been turned off on the admin side.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The request ID to revoke.</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Request ID.</td></tr><tr><td><code>type</code></td><td>string</td><td>Request type: <code>delete</code> or <code>update</code>.</td></tr><tr><td><code>status</code></td><td>string</td><td>Request status — <code>revoked</code> after a successful revoke.</td></tr><tr><td><code>message</code></td><td>string</td><td>The message supplied in the request.</td></tr><tr><td><code>email</code></td><td>string</td><td>Email address tied to the request.</td></tr><tr><td><code>revokedAt</code></td><td>string</td><td>ISO 8601 timestamp when the request was revoked.</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>ISO 8601 creation timestamp.</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>ISO 8601 last update timestamp.</td></tr><tr><td><code>successMessage</code></td><td>string</td><td>Confirmation message — present on create / revoke / delete results.</td></tr><tr><td><code>customer</code></td><td>object</td><td>The customer who owns the request.</td></tr><tr><td><code>customer._id</code></td><td>integer</td><td>Numeric customer ID of the owner.</td></tr></tbody></table><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200 OK</code></td><td>Request revoked.</td></tr><tr><td><code>400 Bad Request</code></td><td>GDPR is disabled in the store&#39;s admin configuration.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid customer Bearer token.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid storefront key.</td></tr><tr><td><code>404 Not Found</code></td><td>The request does not exist or is not owned by the customer.</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>The request is not in a <code>pending</code> or <code>processing</code> state.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">Raise a GDPR Request</a></li><li><a href="/api/rest-api/shop/gdpr-requests/delete-gdpr-request.html">Delete a GDPR Request</a></li><li><a href="/api/rest-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',19)]))}const m=t(s,[["render",o]]);export{p as __pageData,m as default};
